import base64
import json
import os
import sys
from urllib import request


OPENAI_API_URL = "https://api.openai.com/v1/chat/completions"
OPENAI_MODEL = "gpt-4o-mini"


def _read_image(image_path):
    with open(image_path, "rb") as f:
        return f.read()


def describe_image(image_path):
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        raise RuntimeError("OPENAI_API_KEY is required")

    image_bytes = _read_image(image_path)
    image_b64 = base64.b64encode(image_bytes).decode("ascii")
    payload = {
        "model": OPENAI_MODEL,
        "messages": [
            {
                "role": "user",
                "content": [
                    {"type": "text", "text": "Write a short visual description of this image."},
                    {"type": "image_url", "image_url": {"url": f"data:image/jpeg;base64,{image_b64}"}},
                ],
            }
        ],
        "max_tokens": 60,
    }

    req = request.Request(
        OPENAI_API_URL,
        data=json.dumps(payload).encode("utf-8"),
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        },
        method="POST",
    )

    with request.urlopen(req) as resp:
        data = json.loads(resp.read().decode("utf-8"))

    return data["choices"][0]["message"]["content"].strip()


def main():
    if len(sys.argv) != 2:
        raise SystemExit("Usage: describe_image.py <image_path>")
    print(describe_image(sys.argv[1]))


if __name__ == "__main__":
    main()

import base64
import json
import os
import sys
from urllib import request, error


OPENAI_API_URL = "https://api.openai.com/v1/responses"
OPENAI_MODEL = "gpt-4.1-mini"


def detect_text(image_path: str) -> str:
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        raise RuntimeError("OPENAI_API_KEY is required")

    with open(image_path, "rb") as f:
        image_data = base64.b64encode(f.read()).decode("ascii")

    payload = {
        "model": OPENAI_MODEL,
        "input": [
            {
                "role": "user",
                "content": [
                    {"type": "input_text", "text": "Extract all visible text from this image. Return only the text."},
                    {"type": "input_image", "image_url": f"data:image/*;base64,{image_data}"},
                ],
            }
        ],
    }

    req = request.Request(
        OPENAI_API_URL,
        data=json.dumps(payload).encode("utf-8"),
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        },
        method="POST",
    )

    try:
        with request.urlopen(req, timeout=60) as resp:
            data = json.loads(resp.read().decode("utf-8"))
    except error.HTTPError as exc:
        body = exc.read().decode("utf-8", errors="replace")
        raise RuntimeError(f"OpenAI API error: {exc.code} {body}") from exc

    parts = []
    for item in data.get("output", []):
        for content in item.get("content", []):
            if content.get("type") in {"output_text", "text"}:
                text = content.get("text", "")
                if text:
                    parts.append(text)
    return "\n".join(parts).strip()


def main() -> None:
    if len(sys.argv) != 2:
        raise SystemExit("Usage: python detect_image_text.py <image_path>")
    print(detect_text(sys.argv[1]))


if __name__ == "__main__":
    main()

import base64
import json
import os
import sys
from pathlib import Path

import requests


GOOGLE_VISION_ENDPOINT = "https://vision.googleapis.com/v1/images:annotate"


def detect_labels(image_path: str):
    api_key = os.environ.get("GOOGLE_VISION_API_KEY")
    if not api_key:
        raise RuntimeError("GOOGLE_VISION_API_KEY is required")

    data = Path(image_path).read_bytes()
    payload = {
        "requests": [
            {
                "image": {"content": base64.b64encode(data).decode("utf-8")},
                "features": [{"type": "LABEL_DETECTION", "maxResults": 10}],
            }
        ]
    }

    response = requests.post(
        GOOGLE_VISION_ENDPOINT,
        params={"key": api_key},
        json=payload,
        timeout=30,
    )
    response.raise_for_status()
    result = response.json()
    annotations = result.get("responses", [{}])[0].get("labelAnnotations", [])
    return [
        {"description": item.get("description"), "score": item.get("score")}
        for item in annotations
    ]


def main():
    if len(sys.argv) != 2:
        raise SystemExit("usage: detect_image_labels.py IMAGE_PATH")

    labels = detect_labels(sys.argv[1])
    print(json.dumps(labels, indent=2))


if __name__ == "__main__":
    main()
